_health_cache = {"ts": 0.0, "data": None}

_health_compute_lock = _threading.Lock()


@router.get("/api/health")
def get_system_health():
    import time
    now = time.time()
    if _health_cache["data"] and (now - _health_cache["ts"] < 10.0):
        return _health_cache["data"]
    # Only one thread recomputes (it does ~12 sequential network probes, Wazuh alone up to 12s);
    # concurrent callers get the last result instead of piling up behind the same probes.
    if not _health_compute_lock.acquire(blocking=False):
        if _health_cache["data"]:
            return _health_cache["data"]
        _health_compute_lock.acquire()
    try:
        return _compute_system_health()
    finally:
        _health_compute_lock.release()



def _compute_system_health():
    import time
    now = time.time()

    try:
        import shutil

        def check_tool(name):
            return "Online" if shutil.which(name) else "Not Found"

        def check_module(mod_name):
            try:
                __import__(mod_name)
                return "Online"
            except ImportError:
                return "Not Installed"

        def check_db():
            try:
                with db_manager.get_db_connection() as conn:
                    if conn is None:
                        return "Not Configured"
                return "Online"
            except Exception:
                return "Offline"

        def check_ai_engine():
            if os.getenv("GOOGLE_API_KEY") or os.getenv("GROQ_API_KEY"):
                return "Online"
            return "Not Configured"

        def check_http(url, verify=False, timeout=2):
            try:
                requests.get(url, timeout=timeout, verify=verify)
                return "Online"
            except requests.exceptions.SSLError:
                return "Online"
            except Exception:
                return "Unreachable"

        def check_neo4j():
            if not platform_modules.enabled("bloodhound"):
                return "Module Off (no AD data, ADR-0019)"
            try:
                from neo4j import GraphDatabase
                uri = os.getenv("NEO4J_URI", "bolt://neo4j:7687")
                user = os.getenv("NEO4J_USER", "neo4j")
                password = os.getenv("NEO4J_PASSWORD", "password")
                driver = GraphDatabase.driver(uri, auth=(user, password))
                driver.verify_connectivity()
                driver.close()
                return "Online"
            except Exception:
                return "Unreachable"

        def check_vault():
            return "Online" if get_vault_client() else "Unreachable"

        def check_zeek_ingestion():
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("""
                        SELECT COUNT(*) FROM public.runtime_alerts
                        WHERE rule_name ILIKE '%%ZEEK%%' AND detected_at > NOW() - INTERVAL '24 hours'
                    """)
                    return "Online" if cur.fetchone()[0] > 0 else "No Recent Data"
            except Exception:
                return "Unreachable"

        def check_mitre_mapping():
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("SELECT COUNT(*) FROM vulnerability_log WHERE standards IS NOT NULL AND standards != ''")
                    return "Online" if cur.fetchone()[0] > 0 else "No Data Yet"
            except Exception:
                return "Unreachable"

        def check_threat_intel():
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("SELECT COUNT(*) FROM vulnerability_log WHERE threat_intel_checked_at > NOW() - INTERVAL '48 hours'")
                    return "Online" if cur.fetchone()[0] > 0 else "No Recent Data"
            except Exception:
                return "Unreachable"

        def check_cti_feed():
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("""
                        SELECT COUNT(*) FROM public.runtime_alerts
                        WHERE rule_name ILIKE '%%ZEEK-CONN-HEARTBEAT%%' AND detected_at > NOW() - INTERVAL '1 hour'
                    """)
                    return "Online" if cur.fetchone()[0] > 0 else "No Recent Data"
            except Exception:
                return "Unreachable"

        def check_cis_benchmarks():
            if check_module("auditors.auditor_cis_benchmarks") != "Online":
                return "Not Installed"
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("SELECT COUNT(*) FROM vulnerability_log WHERE scan_engine='cis-benchmark'")
                    return "Online" if cur.fetchone()[0] > 0 else "Available (On-Demand, Not Yet Run)"
            except Exception:
                return "Unreachable"

        def check_audit_marker(module_name, marker_cve, max_age_days=8):
            """Real evidence: the audit's own completion marker written within max_age_days."""
            if check_module(module_name) != "Online":
                return "Not Installed"
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("SELECT MAX(detected_at) FROM vulnerability_log WHERE cve_id = %s", (marker_cve,))
                    last = cur.fetchone()[0]
                if last is None:
                    return "Available (Scheduled, Not Yet Run)"
                return "Online" if (datetime.now() - last).days <= max_age_days else "Stale (last run > %dd ago)" % max_age_days
            except Exception:
                return "Unreachable"

        def check_soar_autoresponse():
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("SELECT action_kind, active, dry_run FROM public.autoresponse_policy WHERE active")
                    rows = cur.fetchall()
                if not rows:
                    return "Manual only (no active policy)"
                live = [r[0] for r in rows if not r[2]]
                return f"Autonomous ({', '.join(live)})" if live else "Observation mode (dry-run)"
            except Exception:
                return "Unreachable"

        def check_sonarqube():
            if check_module("auditors.auditor_sonarqube") != "Online":
                return "Not Installed"
            try:
                with db_manager.get_db_cursor() as cur:
                    cur.execute("SELECT COUNT(*) FROM vulnerability_log WHERE scan_engine='sonarqube'")
                    if cur.fetchone()[0] == 0:
                        return "Available (On-Demand, Not Yet Run)"
                from auditors import auditor_sonarqube as _sq
                if _sq.secret_redaction_status().get("enabled") is False:
                    return "Online (Warning: secretos visibles en SonarQube)"
                return "Online"
            except Exception:
                return "Unreachable"

        def measure_latency(func):
            t0 = time.time()
            res = func()
            lat = f"{int((time.time() - t0) * 1000)}ms"
            return res, lat

        def check_wazuh_manager():
            return check_http("https://192.0.2.17:55000", timeout=2)

        def check_containment_status():
            w_status = check_wazuh_manager()
            if w_status == "Online":
                return "Operational (Active-Response EDR Active)"
            return "Available (On-Demand)"

        db_st, db_lat = measure_latency(check_db)
        ai_st, ai_lat = measure_latency(check_ai_engine)
        vault_st, vault_lat = measure_latency(check_vault)
        wazuh_st, wazuh_lat = measure_latency(check_wazuh_manager)
        auth_st, auth_lat = measure_latency(lambda: check_http(org_config.AUTHENTIK_URL, timeout=2))
        cont_st, cont_lat = measure_latency(check_containment_status)

        zap_status = "Online" if check_tool("docker") == "Online" and check_module("auditors.auditor_zap") == "Online" else "Not Found"
        from core import engine_status as _es
        try:
            with db_manager.get_db_cursor() as _cur:
                _eng = {e["engine"]: e for e in _es.compute(_es.read_rows(_cur))}
        except Exception:
            import traceback; traceback.print_exc()
            _eng = {}

        def _with_data(tool_status, engine):
            """'Online' only when the engine also produced data; an installed-but-silent tool is reported as such (it used to read Online)."""
            e = _eng.get(engine)
            if tool_status != "Online" or not e:
                return tool_status
            if e["total"] == 0:
                return f"No Data (instalado, pero '{engine}' nunca ha producido un hallazgo{'; ' + e['note'] if e['note'] else ''})"
            if e["state"] == "OBSOLETO":
                return f"Stale (último hallazgo de '{engine}' hace {e['days_since_last']} días)"
            return tool_status

        secrets_status = _with_data(check_tool("trufflehog"), "secrets")
        engines_summary = _es.health_summary(list(_eng.values())) if _eng else "No Data (no se pudo leer la BD)"

        res = {
            "status": "Healthy" if db_st == "Online" else "Degraded",
            "services": [
                {"name": "Database Maestro", "status": db_st, "latency": db_lat},
                {"name": "AI Engine (Gemini/Groq)", "status": ai_st, "latency": ai_lat},
                {"name": "Scanning Engine (Nuclei)", "status": check_tool("nuclei"), "latency": "5ms"},
                {"name": "DAST Engine (ZAP)", "status": zap_status, "latency": "12ms"},
                {"name": "Secrets Scanner (TruffleHog)", "status": secrets_status, "latency": "4ms"},
                {"name": "Scan Engines (data freshness)", "status": engines_summary, "latency": "DB"},
                {"name": "OSINT Engine (SpiderFoot)", "status": check_module("auditors.auditor_spiderfoot"), "latency": "3ms"},
                {"name": "Container Scanner (Trivy)", "status": check_tool("trivy"), "latency": "6ms"},
                {"name": "NDR (Zeek)", "status": check_zeek_ingestion(), "latency": "2ms"},
                {"name": "ITDR (Neo4j/BloodHound)", "status": check_neo4j(), "latency": "15ms"},
                {"name": "Telemetría ClickHouse (ITDR/UEBA)", "status": "Online" if platform_modules.enabled("clickhouse")
                    else "Module Off (no events ever stored, ADR-0019)", "latency": "-"},
                {"name": "Secrets Backend (OpenBao)", "status": vault_st, "latency": vault_lat},
                {"name": "EDR (Wazuh Manager)", "status": wazuh_st, "latency": wazuh_lat},
                {"name": "Identity (Authentik)", "status": auth_st, "latency": auth_lat},
                {"name": "Risk Intel (EPSS/CISA KEV)", "status": check_threat_intel(), "latency": "10ms"},
                {"name": "CTI Feed (C2/IOC Matching)", "status": check_cti_feed(), "latency": "4ms"},
                {"name": "MITRE ATT&CK Mapping", "status": check_mitre_mapping(), "latency": "3ms"},
                {"name": "CIS Benchmarks (Hardening Audit)", "status": check_cis_benchmarks(), "latency": "5ms"},
                {"name": "SonarQube (Code Quality Gate)", "status": check_sonarqube(), "latency": "5ms"},
                {"name": "OS Patch & EOL Audit", "status": check_audit_marker("auditors.auditor_os_patches", "OS-PATCH-AUDIT"), "latency": "4ms"},
                {"name": "TLS Posture Audit", "status": check_audit_marker("auditors.auditor_tls", "TLS-AUDIT"), "latency": "4ms"},
                {"name": "GitLab Config & CI/CD Audit", "status": check_audit_marker("auditors.auditor_gitlab_config", "GITLAB-CONFIG-AUDIT", 2), "latency": "4ms"},
                {"name": "SOAR Autoresponse (Policy)", "status": check_soar_autoresponse(), "latency": "4ms"},
                {"name": "GitLab Auto-Fix (MR Patcher)", "status": check_module("remediation.gitlab_autofix"), "latency": "2ms"},
                {"name": "Host Containment (Emergency Response)", "status": cont_st, "latency": cont_lat},
            ],
            "scan_modules": {
                "nuclei": check_tool("nuclei"),
                "zap_dast": zap_status,
                "secrets": secrets_status,
                "spiderfoot_osint": check_module("auditors.auditor_spiderfoot"),
                "trivy": check_tool("trivy"),
                "nmap": check_tool("nmap"),
                "sqlmap": check_tool("sqlmap"),
                "cis_benchmarks": check_cis_benchmarks(),
                "sonarqube": check_sonarqube(),
                "mitre_attack_mapping": check_mitre_mapping(),
                "threat_intel_epss_kev": check_threat_intel(),
                "cti_feed_c2": check_cti_feed(),
                "gitlab_autofix": check_module("remediation.gitlab_autofix"),
                "host_containment": cont_st,
            },
            "last_check": datetime.now().isoformat()
        }
        _health_cache["ts"] = now
        _health_cache["data"] = res
        return res
    except Exception as e:
        return {"status": "Degraded", "error": str(e)}



@router.post("/api/wazuh/agent/{agent_id}/action")
def wazuh_agent_action(agent_id: str, action: str):
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT asset_name, endpoint FROM public.infra_inventory WHERE agent_id = %s", (agent_id,))
            asset = cur.fetchone()
            
        if not asset:
            raise HTTPException(status_code=404, detail="Agent not found in inventory")
            
        if action == "restart":
            cmd = ["docker", "exec", org_config.WAZUH_MANAGER_CONTAINER, "/var/ossec/bin/agent_control", "-r", "-a", agent_id]
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            if res.returncode == 0:
                return {"status": "success", "message": f"Restart command sent to agent {agent_id}"}
            else:
                raise Exception(res.stderr)
        elif action == "scan":
            cmd = ["docker", "exec", org_config.WAZUH_MANAGER_CONTAINER, "/var/ossec/bin/agent_control", "-s", "-a", agent_id]
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            if res.returncode == 0:
                return {"status": "success", "message": f"FIM/Syscheck scan triggered for agent {agent_id}"}
            else:
                raise Exception(res.stderr)
        elif action == "logs":
            cmd = ["docker", "exec", org_config.WAZUH_MANAGER_CONTAINER, "tail", "-n", "100", "/var/ossec/logs/ossec.log"]
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            if res.returncode == 0:
                log_lines = res.stdout.splitlines()
                matched = [line for line in log_lines if agent_id in line or asset["asset_name"] in line]
                if not matched:
                    matched = ["No recent events found for this agent in manager log."]
                return {"logs": matched}
            else:
                raise Exception(res.stderr)
        elif action in ("uninstall", "delete"):
            cmd = ["docker", "exec", org_config.WAZUH_MANAGER_CONTAINER, "/var/ossec/bin/manage_agents", "-r", agent_id]
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=15)
            with db_manager.get_db_cursor() as cur:
                cur.execute("UPDATE public.infra_inventory SET agent_id = NULL, status = 'uninstalled' WHERE agent_id = %s OR asset_name = %s", (agent_id, asset["asset_name"]))
            return {"status": "success", "message": f"Agente Wazuh {agent_id} desinstalado y removido del inventario."}
        else:
            raise HTTPException(status_code=400, detail="Invalid action")
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.post("/api/wazuh/agent/{agent_id}/uninstall")
def uninstall_wazuh_agent(agent_id: str):
    """
    Uninstalls the Wazuh agent from its host and deregisters it from the Manager. Requires
    Ansible credentials (sudo password or SSH key) already stored in Vault for the asset --
    same requirement as any other Ansible-driven action in this app -- so this never falls
    back to a shared/default credential for a destructive host-level action.
    """
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT asset_name, endpoint FROM public.infra_inventory WHERE agent_id = %s", (agent_id,))
            asset = cur.fetchone()

        if not asset:
            raise HTTPException(status_code=404, detail="Agent not found in inventory")

        creds = get_ansible_credentials(asset["asset_name"])
        # Deliberately does not accept the shared the shared default key (SSH_DEFAULT_KEY) as sufficient here --
        # unlike install, this destructive action requires a credential explicitly stored in
        # Vault for this specific asset, not an implicit master key that happens to work on
        # every host.
        if not creds["sudo_password"] and not creds["ssh_private_key"]:
            raise HTTPException(
                status_code=400,
                detail=f"No hay credenciales de Ansible en Vault para '{asset['asset_name']}'. Configura una contraseña sudo o llave SSH (botón Vault) antes de desinstalar."
            )

        uninstall_wazuh_agent_background(
            agent_id=agent_id,
            asset_name=asset["asset_name"],
            endpoint=asset["endpoint"],
            user=creds["ansible_user"] or "authentik",
            password=creds["sudo_password"] or None,
            ssh_private_key=creds["ssh_private_key"] or None
        )
        return {"status": "queued", "message": f"Desinstalación del agente {agent_id} en curso. Revisa el estado del activo en unos minutos."}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



# Real Authentik usernames are alphanumeric plus a small set of separators (matches Authentik's
# own username validation) -- rejecting anything else closes off the Python-string-breaking
# injection vector (quotes, backslashes, semicolons) for the remote `manage.py shell -c` call.
_AUTHENTIK_USERNAME_RE = re.compile(r"^[A-Za-z0-9._@-]{1,150}$")



def _validate_authentik_username(username: str) -> str:
    if not _AUTHENTIK_USERNAME_RE.match(username or ""):
        raise HTTPException(status_code=400, detail="Nombre de usuario inválido.")
    return username



@router.get("/api/engines/status")
def engines_status():
    """What every scan engine has actually produced (rows, last detection, state), from vulnerability_log -- not from whether its binary is installed."""
    from core import engine_status
    with db_manager.get_db_cursor() as cur:
        entries = engine_status.compute(engine_status.read_rows(cur))
    counts = {}
    for e in entries:
        counts[e["state"]] = counts.get(e["state"], 0) + 1
    return {"summary": engine_status.health_summary(entries), "counts": counts, "engines": entries}


@router.get("/api/users/me", summary="Rol y datos del usuario actual")
def get_current_user(request: Request):
    """The caller's identity and Centinela role, taken from the validated session token (no Authentik round trip).
    role: Admin / Analyst / Auditor / Viewer, or Disabled when the token carries no Centinela group. The dashboard uses this to
    decide what it shows; the API enforces the same role in core.roles."""
    from core import roles
    claims = getattr(request.state, "user", None) or {}
    role = roles.role_of(claims) or "Disabled"
    return {"username": claims.get("preferred_username") or claims.get("sub"), "email": claims.get("email"),
            "name": claims.get("name"), "role": role, "role_mode": roles.mode()}


@router.get("/api/users")
def get_authentik_users():
    """Lists all non-system users from Authentik with their assigned Centinela RBAC role
    (Admin / Analyst / Auditor / Viewer / Disabled). `Disabled` = member of no Centinela group;
    the Authentik `centinela-ai` application only admits members of the four role groups
    (see ensure_centinela_app_access_policy), so such a user cannot sign in to Centinela.

    Plain `def` on purpose: this blocks on an SSH call for seconds, and as `async def` it
    stalled the whole event loop (every dashboard request behind it returned 504)."""
    try:
        # single physical line -- comprehension + lambda, no `for`/`if` blocks, no newlines
        # (see _run_authentik_ssh_command's docstring for why the old multi-line form never ran)
        remote_snippet = (
            "import json; from authentik.core.models import User, Group; "
            "roles={'Admin':Group.objects.filter(name='Centinela Admin').first(),"
            "'Analyst':Group.objects.filter(name='Centinela Analyst').first(),"
            "'Auditor':Group.objects.filter(name='Centinela Auditor').first(),"
            "'Viewer':Group.objects.filter(name='Centinela Viewer').first()}; "
            "pick=lambda u: next((r for r,g in roles.items() if g and g in u.groups.all()),'Disabled'); "
            "data=[{'username':u.username,'name':u.name or u.username,'email':u.email,'role':pick(u)} "
            "for u in User.objects.all() if not u.username.startswith('ak-') and u.username!='AnonymousUser']; "
            "print('JSON_DATA:'+json.dumps(sorted(data, key=lambda d: d['username'].lower())))"
        )
        proc = _run_authentik_ssh_command(remote_snippet)
        out = proc.stdout or ""
        for line in out.splitlines():
            if line.startswith("JSON_DATA:"):
                return json.loads(line[len("JSON_DATA:"):])
        # Rule #6: never swallow -- surface why the list is empty instead of a silent []
        print(f"⚠️ [Authentik] /api/users got no JSON_DATA (rc={proc.returncode}). "
              f"stdout tail: {out[-300:]!r} | stderr tail: {(proc.stderr or '')[-500:]!r}")
        raise HTTPException(status_code=502,
                            detail="Authentik no devolvió la lista de usuarios (ver logs del backend).")
    except HTTPException:
        raise
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=504, detail="Authentik tardó demasiado en responder (shell frío).")
    except Exception as e:
        import traceback; traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))



class UserRoleUpdateModel(BaseModel):
    username: str
    role: str  # "Admin", "Analyst", "Auditor", "Viewer", or "Disabled" (removes every Centinela group)



@router.post("/api/users/role")
def update_authentik_user_role(body: UserRoleUpdateModel, request: Request):
    """Updates a user's RBAC role in Authentik (Centinela Admin / Analyst / Auditor / Viewer, or
    Disabled = no Centinela group, which the Authentik app policy turns into "cannot sign in")."""
    ROLE_ALLOWLIST = ("Admin", "Analyst", "Auditor", "Viewer", "Disabled")
    try:
        new_role = body.role
        username = _validate_authentik_username(body.username)
        # Real, exploitable injection previously here (see _run_authentik_ssh_command's
        # docstring): new_role/username went straight into an f-string executed with
        # shell=True. Checking new_role against a fixed enum closes that vector for the role
        # value entirely (rather than trying to escape it).
        if new_role not in ROLE_ALLOWLIST:
            raise HTTPException(status_code=400, detail=f"Rol inválido. Debe ser uno de: {', '.join(ROLE_ALLOWLIST)}")
        # single physical line -- list-comprehension side effects instead of `for`/`if` blocks
        # (a `\\n`-joined multi-line snippet is a SyntaxError under the remote exec(); this
        # endpoint silently 404'd on every call before this fix)
        remote_snippet = (
            "from authentik.core.models import Group; from authentik.core.models import User; "
            "groups={r:Group.objects.get_or_create(name='Centinela '+r)[0] for r in ['Admin','Analyst','Auditor','Viewer']}; "
            f"u=User.objects.filter(username='{username}').first(); "
            "_=[u.groups.remove(g) for g in groups.values()] if u else None; "
            f"_=(u.groups.add(groups['{new_role}'])) if (u and '{new_role}' in groups) else None; "
            "print('ROLE_UPDATED_SUCCESS' if u else 'USER_NOT_FOUND')"
        )
        proc = _run_authentik_ssh_command(remote_snippet)
        if "ROLE_UPDATED_SUCCESS" in proc.stdout:
            caller = getattr(request.state, "user", None) or {}
            agent_ledger.record_action("user_role_changed", f"Rol de {username} -> {new_role}", entity_type="user", entity_id=username,
                                       actor=str(caller.get("preferred_username") or caller.get("sub") or "unknown"),
                                       detail={"username": username, "role": new_role})
            return {"status": "success", "username": username, "role": new_role}
        if "USER_NOT_FOUND" in proc.stdout:
            raise HTTPException(status_code=404, detail="Usuario no encontrado en Authentik")
        print(f"⚠️ [Authentik] /api/users/role no confirmó (rc={proc.returncode}). "
              f"stdout: {proc.stdout[-300:]!r} | stderr: {(proc.stderr or '')[-500:]!r}")
        raise HTTPException(status_code=502, detail="Authentik no confirmó el cambio de rol (ver logs del backend).")
    except HTTPException:
        raise
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=504, detail="Authentik tardó demasiado en responder.")
    except Exception as e:
        import traceback; traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))



